std::vector<Polygon2d> result;
for (auto fit = arr.faces_begin(); fit != arr.faces_end(); ++fit) {
    if (fit->is_unbounded()) continue;
    Polygon2d poly;
    for (auto he = fit->outer_ccb(); he != nullptr; he = he->next()) {
        const auto& pt = he->source()->point();
        poly.push_back(Point2d(CGAL::to_double(pt.x()), CGAL::to_double(pt.y())));
    }
    result.push_back(poly);
}
return result;

